#### Test dredging_trajectories() ####
## correct results
test_that("dredge_trajectories correctly generates full table, within delta criterion table and best model table", {

  set.seed(123)

  # standardized data to avoid scaling warnings
  data <- data.frame(x = rnorm(100, mean = 0, sd = 1),
                     y = rnorm(100, mean = 0, sd = 1),
                     z = rnorm(100, mean = 0, sd = 1),
                     group = factor(c(rep("A", 25), rep("B", 25), rep("C", 25), rep("D", 25))))

  # formulas generated by trajectory_formulas()
  f_lmer <- trajectory_formulas(formula = y ~ x + (1|group),
                                trajectory_trait = "z",
                                interactions = "x",
                                data = data,
                                trajectories = c("linear", "quadratic", "thresholdCS", "thresholdSS"))

  # threshold estimation with estimate_threshold()
  estimation_lmer <- estimate_threshold(data = data,
                                        threshold_formulas = f_lmer,
                                        trajectory_trait = "z",
                                        start = -0.8, end = 0.8, iter = 0.2,
                                        rank = "AICc")

  # model fitting with fit_models()
  fit_lmer <- fit_models(formulas = f_lmer,
                         trajectory_trait = "z",
                         data = data,
                         best_thresholds = estimation_lmer,
                         lmer_control = NULL)

  res <- dredge_trajectories(models = fit_lmer,
                             trajectory_trait = "z",
                             rank = "AICc",
                             delta_criterion = 2,
                             data = data)

  # ---- test expected output structure ----
  expect_equal(class(res), "dredge.results")
  expect_type(res, "list")
  expect_length(res, 6)

  ## dredge tables
  ### full table
  expect_type(res$full_table, "list")
  expect_length(res$full_table, length(fit_lmer$models))
  expect_true(all(vapply(res$full_table, function(x) inherits(x, "model.selection"), logical(1))))
  expect_equal(names(res$full_table), names(fit_lmer$models))

  ### under delta table
  expect_type(res$all_under_delta, "list")
  expect_length(res$all_under_delta, length(fit_lmer$models))
  expect_true(all(vapply(res$all_under_delta, function(x) inherits(x, "model.selection"), logical(1))))
  expect_equal(names(res$all_under_delta), names(fit_lmer$models))

  ### lowest df table
  expect_type(res$min_df, "list")
  expect_length(res$min_df, length(fit_lmer$models))
  expect_true(all(vapply(res$min_df, function(x) inherits(x, "model.selection"), logical(1))))
  expect_equal(names(res$min_df), names(fit_lmer$models))

  ### best model table
  expect_type(res$best_models, "list")
  expect_length(res$best_models, length(fit_lmer$models))
  expect_true(all(vapply(res$best_models, function(x) inherits(x, "model.selection"), logical(1))))
  expect_equal(names(res$best_models), names(fit_lmer$models))

  ## rank
  expect_type(res$rank, "character")
  expect_length(res$rank, 1)
  expect_equal(res$rank, "AICc")

  ## model_env
  expect_type(res$model_env, "environment")
  expect_length(res$model_env, length(fit_lmer$best_thresholds) + 1) # +1 for data

  # ---- test tables structures ----
  ## all_under_delta tables have only models within 2 delta AIC(c) and is a subset of full_table
  expect_true(all(vapply(res$all_under_delta, function(x) all(x$delta <= 2), logical(1))))

  expect_true(all(mapply(function(full, under) {
    all(max(under$rank) <= max(full$rank))
  }, res$full_table, res$all_under_delta)))

  ## min_df tables have systematically <= number of parameters than in all_under_delta tables and is a subset of all_under_delta
  expect_true(all(mapply(function(under, min) {
    all(min$df <= under$df)
  }, res$all_under_delta, res$min_df)))

  expect_true(all(mapply(function(under, min) {
    all(max(min$rank) <= max(under$rank))
  }, res$all_under_delta, res$min_df)))

  ## best_models tables have only 1 row (if not, df and rank are all equal) and is a subset of min_df
  expect_true(all(vapply(res$best_models, function(x) {
    all(nrow(x) == 1 || length(unique(x$df)) == 1 && length(unique(x$rank)) == 1)
    }, logical(1))))

  expect_true(all(mapply(function(min, best) {
    all(best$rank <= max(min$rank))
  }, res$min_df, res$best_models)))

  # ---- model environment ----
  ## threshold datasets exist in the models environment
  expect_true(exists(".data_CS", envir = res$model_env, inherits = FALSE))
  expect_true(exists(".data_SS", envir = res$model_env, inherits = FALSE))
  expect_true(exists("data", envir = res$model_env, inherits = FALSE))

  ## threshold datasets are data.frame objects
  expect_true(is.data.frame(get(".data_CS", envir = res$model_env)))
  expect_true(is.data.frame(get(".data_SS", envir = res$model_env)))
  expect_true(is.data.frame(get("data", envir = res$model_env)))
})

## errors when invalid arguments
test_that("dredge_thrajectories errors when invalid arguments", {

  set.seed(123)

  # standardized data to avoid scaling warnings
  data <- data.frame(x = rnorm(100, mean = 0, sd = 1),
                     y = rnorm(100, mean = 0, sd = 1),
                     z = rnorm(100, mean = 0, sd = 1),
                     group = factor(c(rep("A", 25), rep("B", 25), rep("C", 25), rep("D", 25))))

  # formulas generated by trajectory_formulas()
  f_lmer <- trajectory_formulas(formula = y ~ x + (1|group),
                                trajectory_trait = "z",
                                interactions = "x",
                                data = data,
                                trajectories = c("linear", "quadratic", "thresholdCS", "thresholdSS"))

  # threshold estimation with estimate_threshold()
  estimation_lmer <- estimate_threshold(data = data,
                                        threshold_formulas = f_lmer,
                                        trajectory_trait = "z",
                                        start = -0.8, end = 0.8, iter = 0.2,
                                        rank = "AICc")

  # model fitting with fit_models()
  fit_lmer <- fit_models(formulas = f_lmer,
                         trajectory_trait = "z",
                         data = data,
                         best_thresholds = estimation_lmer,
                         lmer_control = NULL)

  # ---- data ----
  wrongdata <- "not a data.frame"
  expect_error(
      dredge_trajectories(models = fit_lmer,
                          trajectory_trait = "z",
                          rank = "AICc",
                          delta_criterion = 2,
                          data = wrongdata),
      "data must be provided and must be an existing data.frame")

  # ---- models ----
  ## not a "models" object
  not.models <- lmer(y ~ x + x:z + (1|group), data = data, REML = FALSE)
  expect_error(
      dredge_trajectories(models = not.models,
                          trajectory_trait = "z",
                          rank = "AICc",
                          delta_criterion = 2,
                          data = data),
      "models must be a list of 'models' class objects returned by fit_models()")

  # ---- trajectory_trait ----
  ## not a single character
  expect_error(
      dredge_trajectories(models = fit_lmer,
                          trajectory_trait = c("z", "x"),
                          rank = "AICc",
                          delta_criterion = 2,
                          data = data),
      "trajectory_trait must be a single character string")

  ## not a character string
  expect_error(
      dredge_trajectories(models = fit_lmer,
                          trajectory_trait = 123,
                          rank = "AICc",
                          delta_criterion = 2,
                          data = data),
      "trajectory_trait must be a single character string")

  ## not a variable of data
  wrongvar <- "not a variable of data"
  expect_error(
      dredge_trajectories(models = fit_lmer,
                          trajectory_trait = wrongvar,
                          rank = "AICc",
                          delta_criterion = 2,
                          data = data),
      "trajectory_trait must be a variable of 'data'")

  # ---- delta_criterion ----
  ## not a numeric
  wrongdelta <- "not a numeric"
  expect_error(
      dredge_trajectories(models = fit_lmer,
                          trajectory_trait = "z",
                          rank = "AICc",
                          delta_criterion = wrongdelta,
                          data = data),
      "delta_criterion must be a single non-negative numeric value")

  ## not a single numeric value
  expect_error(
      dredge_trajectories(models = fit_lmer,
                          trajectory_trait = "z",
                          rank = "AICc",
                          delta_criterion = c(2, 4),
                          data = data),
      "delta_criterion must be a single non-negative numeric value")

  ## NA
  expect_error(
      dredge_trajectories(models = fit_lmer,
                          trajectory_trait = "z",
                          rank = "AICc",
                          delta_criterion = NA,
                          data = data),
      "delta_criterion must be a single non-negative numeric value")

  ## negative value
  expect_error(
      dredge_trajectories(models = fit_lmer,
                          trajectory_trait = "z",
                          rank = "AICc",
                          delta_criterion = -2,
                          data = data),
      "delta_criterion must be a single non-negative numeric value")
})

#### Test best_trajectory() ####
## correct results
test_that("best_trajectory correctly returns the recap table, final trajectory and summaries", {

  set.seed(123)

  # standardized data to avoid scaling warnings
  data <- data.frame(x = rnorm(100, mean = 0, sd = 1),
                     y = rnorm(100, mean = 0, sd = 1),
                     z = rnorm(100, mean = 0, sd = 1),
                     group = factor(c(rep("A", 25), rep("B", 25), rep("C", 25), rep("D", 25))))

  # formulas generated by trajectory_formulas()
  f_lmer <- trajectory_formulas(formula = y ~ x + (1|group),
                                trajectory_trait = "z",
                                interactions = "x",
                                data = data,
                                trajectories = c("linear", "quadratic", "thresholdCS", "thresholdSS"))

  # threshold estimation with estimate_threshold()
  estimation_lmer <- estimate_threshold(data = data,
                                        threshold_formulas = f_lmer,
                                        trajectory_trait = "z",
                                        start = -0.8, end = 0.8, iter = 0.2,
                                        rank = "AICc")

  # model fitting with fit_models()
  fit_lmer <- fit_models(formulas = f_lmer,
                         trajectory_trait = "z",
                         data = data,
                         best_thresholds = estimation_lmer,
                         lmer_control = NULL)

  dredge_results <- dredge_trajectories(models = fit_lmer,
                                        trajectory_trait = "z",
                                        rank = "AICc",
                                        delta_criterion = 2,
                                        data = data)

  res <- best_trajectory(dredge_results,
                         delta_criterion = 2,
                         adjust_threshold = FALSE)

  res_adj <- best_trajectory(dredge_results,
                             delta_criterion = 2,
                             adjust_threshold = TRUE)

  # ---- test expected output structure ----
  expect_equal(class(res), "best.trajectory")
  expect_type(res, "list")
  expect_length(res, 5)

  ## best_table
  expect_s3_class(res$best_table, "data.frame")
  expect_equal(res$best_table$trajectory, names(dredge_results$best_models))
  expect_equal(nrow(res$best_table), length(dredge_results$best_models))

  ## final_traj
  expect_s3_class(res$final_traj, "data.frame")

  ## final_traj_name
  expect_type(res$final_traj_name, "character")

  ## summaries
  expect_type(res$summaries, "list")
  expect_equal(names(res$summaries), names(dredge_results$best_models))
  expect_equal(length(res$summaries), length(dredge_results$best_models))
  expect_true(all(vapply(res$summaries, function(x) inherits(x, "summary.merMod"), logical(1))))

  ## final_summary
  expect_type(res$final_summary, "list")
  expect_equal(names(res$final_summary), res$final_traj$trajectory)
  expect_equal(length(res$final_summary), nrow(res$final_traj))
  expect_true(all(vapply(res$final_summary, function(x) inherits(x, "summary.merMod"), logical(1))))

  # ---- test results coherence ----
  ## ajust_threshold correctly increment df and rank
  expect_equal(res$best_table$df[grepl("threshold", res$best_table$trajectory)] + 1, res_adj$best_table$df[grepl("threshold", res_adj$best_table$trajectory)])
  expect_equal(res$best_table$AICc[grepl("threshold", res$best_table$trajectory)] + 2, res_adj$best_table$AICc[grepl("threshold", res_adj$best_table$trajectory)])

  ## final_traj have only models under 2 delta AICc
  expect_true(all(res$final_traj$delta <= 2))

  ## final_traj_name is a paste of trajectories in final_traj
  expect_equal(paste(res$final_traj$trajectory, collapse = ", "), res$final_traj_name)
})

## errors when invalid arguments
test_that("best_trajectory correctly errors when invalid arguments", {

  set.seed(123)

  # standardized data to avoid scaling warnings
  data <- data.frame(x = rnorm(100, mean = 0, sd = 1),
                     y = rnorm(100, mean = 0, sd = 1),
                     z = rnorm(100, mean = 0, sd = 1),
                     group = factor(c(rep("A", 25), rep("B", 25), rep("C", 25), rep("D", 25))))

  # formulas generated by trajectory_formulas()
  f_lmer <- trajectory_formulas(formula = y ~ x + (1|group),
                                trajectory_trait = "z",
                                interactions = "x",
                                data = data,
                                trajectories = c("linear", "quadratic", "thresholdCS", "thresholdSS"))

  # threshold estimation with estimate_threshold()
  estimation_lmer <- estimate_threshold(data = data,
                                        threshold_formulas = f_lmer,
                                        trajectory_trait = "z",
                                        start = -0.8, end = 0.8, iter = 0.2,
                                        rank = "AICc")

  # model fitting with fit_models()
  fit_lmer <- fit_models(formulas = f_lmer,
                         trajectory_trait = "z",
                         data = data,
                         best_thresholds = estimation_lmer,
                         lmer_control = NULL)

  dredge_results <- dredge_trajectories(models = fit_lmer,
                                        trajectory_trait = "z",
                                        rank = "AICc",
                                        delta_criterion = 2,
                                        data = data)

  # ---- dredge_results ----
  wrong.dredge.results <- "not a dredge.results object"
  expect_error(
    best_trajectory(dredge_results = wrong.dredge.results,
                    delta_criterion = 2,
                    adjust_threshold = FALSE),
    "dredge_results must be a list of 'dredge.results' class objects returned by dredge_trajectories()")

  expect_error(
    best_trajectory(dredge_results = list(123),
                    delta_criterion = 2,
                    adjust_threshold = FALSE),
    "dredge_results must be a list of 'dredge.results' class objects returned by dredge_trajectories()")

  # ---- delta_criterion ----
  ## not a numeric
  expect_error(
    best_trajectory(dredge_results,
                    delta_criterion = "2",
                    adjust_threshold = FALSE),
    "delta_criterion must be a single non-negative numeric value")

  ## not a single numeric
  expect_error(
    best_trajectory(dredge_results,
                    delta_criterion = c(2, 4),
                    adjust_threshold = FALSE),
    "delta_criterion must be a single non-negative numeric value")

  ## not a non-negative numeric
  expect_error(
    best_trajectory(dredge_results,
                    delta_criterion = -2,
                    adjust_threshold = FALSE),
    "delta_criterion must be a single non-negative numeric value")
})

#### Test print.best.trajectory() ####
test_that("print.best.trajectory works", {

  set.seed(123)

  # standardized data to avoid scaling warnings
  data <- data.frame(x = rnorm(100, mean = 0, sd = 1),
                     y = rnorm(100, mean = 0, sd = 1),
                     z = rnorm(100, mean = 0, sd = 1),
                     group = factor(c(rep("A", 25), rep("B", 25), rep("C", 25), rep("D", 25))))

  # formulas generated by trajectory_formulas()
  f_lmer <- trajectory_formulas(formula = y ~ x + (1|group),
                                trajectory_trait = "z",
                                interactions = "x",
                                data = data,
                                trajectories = c("linear", "quadratic", "thresholdCS", "thresholdSS"))

  # threshold estimation with estimate_threshold()
  estimation_lmer <- estimate_threshold(data = data,
                                        threshold_formulas = f_lmer,
                                        trajectory_trait = "z",
                                        start = -0.8, end = 0.8, iter = 0.2,
                                        rank = "AICc")

  # model fitting with fit_models()
  fit_lmer <- fit_models(formulas = f_lmer,
                         trajectory_trait = "z",
                         data = data,
                         best_thresholds = estimation_lmer,
                         lmer_control = NULL)

  dredge_results <- dredge_trajectories(models = fit_lmer,
                                        trajectory_trait = "z",
                                        rank = "AICc",
